window.AUTH=window.AUTH||{};window.AUTH["18-485"]={"d":"18-485","id":"2018/18-485","n":"McDonough v. Smith","briefs":[{"k":"petitioner","label":"Brief of petitioner Edward G. McDonough","date":"2019-02-25","url":"https://www.supremecourt.gov/DocketPDF/18/18-485/89486/20190225134006399_18-485ts.pdf","side":"pet","n":114},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-03-04","url":"https://www.supremecourt.gov/DocketPDF/18/18-485/90617/20190304182911799_18-485tsacUnited%20States.pdf","side":"us","n":46},{"k":"respondent","label":"Brief of respondent Youel Smith","date":"2019-03-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-485/93456/20190327171107114_18-485%20bs.pdf","side":"res","n":42},{"k":"reply","label":"Reply of petitioner Edward G. McDonough","date":"2019-04-10","url":"https://www.supremecourt.gov/DocketPDF/18/18-485/95930/20190410110158017_McDonough%20Reply%20FINAL.PDF","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/588US1PP_web.pdf#page=117","tr":true,"items":[{"t":"case","label":"Afro-Lecon, Inc. v. United States","cite":"820 F.2d 1198","y":1987,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/820/1198/","by":{"0":"57"}},{"t":"case","label":"Agency Holding Corp. v. Malley-Duff & Assocs., Inc.","cite":"483 U.S. 143","y":1987,"id":"1986/86-497","sc":1,"sum":"In February 1978, petitioner Crown Life Insurance Co. terminated its relationship with its agent, respondent Malley-Duff & Associates (MalleyDuff), for failure to satisfy a production quota. Alleging, inter alia, that the real reason for the termination was petitioners' desire to acquire its lucrative territory, Malley-Duff brought suit in March 1981 under the Racketeer Influenced and Corrupt Organizations Act …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Albright v. Oliver","cite":"510 U.S. 266","y":1994,"id":"1993/92-833","sc":1,"op":3,"ar":1,"sum":"The Court ruled that Section 1983 relief for prosecution without probable cause is only valid if the prosecuted party claims Fourth Amendment (pretrial rights) violations.","sumSrc":"Oyez","by":{"0":"40, 42, 47","1":"16","2":"22","3":"6, 19"}},{"t":"case","label":"Avery v. City of Milwaukee","cite":"847 F.3d 433","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/433/","by":{"0":"51"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Tr. Fund v. Ferbar Corp. of Cal.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"0":"3, 15, 21, 31","1":"11"}},{"t":"case","label":"Bell Atlantic Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"0":"56"}},{"t":"case","label":"Beltran v. Santa Clara Cty.","cite":"514 F.3d 906","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/514/906/","by":{"0":"25"}},{"t":"case","label":"Black v. Montgomery Cty.","cite":"835 F.3d 358","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/835/358/","by":{"0":"51","1":"14, 25","3":"3, 14, 20"}},{"t":"case","label":"Blackledge v. Perry","cite":"417 U.S. 21","y":1974,"id":"1973/72-1660","sc":1,"sum":"Respondent, a North Carolina prison inmate, had an altercation with another prisoner, and was charged with the misdemeanor of assault with a deadly weapon, of which he was convicted in the State District Court. While respondent's subsequent appeal was pending in the Superior Court, where he had the right to a trial de novo, the prosecutor obtained an indictment covering the same conduct for the felony offense of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"Bordenkircher v. Hayes","cite":"434 U.S. 357","y":1978,"id":"1977/76-1334","sc":1,"sum":"The Court held that the defendant's due process rights were not violated in this case. Justice Stewart spent some time describing the important role that plea bargaining plays in the nation's legal system, a role that has been accepted by the Supreme Court in cases such as Blackledge v. Allison (1977) and Brady v. United States (1970).","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"Boyd v. Farrin","cite":"575 F. App’x 517","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/575/517/","by":{"0":"56, 57"}},{"t":"case","label":"Bradford v. Scherschligt","cite":"803 F.3d 382","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/382/","op":1,"sum":"Noting “distinctive” rule for malicious prosecution.","sumSrc":"brief:3","by":{"0":"13, 19, 24, 26","3":"7"}},{"t":"case","label":"Briscoe v. LaHue","cite":"460 U.S. 325","y":1983,"id":"1982/81-1404","sc":1,"sum":"Title 42 U. S. C. § 1983 (1976 ed., Supp. V) does not authorize a convicted state defendant to assert a claim for damages against a police officer for giving perjured testimony at the defendant's criminal trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39, 41"}},{"t":"case","label":"Caldwell v. City & Cty. of San Francisco","cite":"889 F.3d 1105","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/889/1105/","by":{"0":"51"}},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"ar":1,"sum":"The Court held that the purpose of the Civil Rights Act of 1871 is to compensate people for injuries caused by the deprivation of civil rights, which means that compensation cannot occur without proof of injury. However, the definition of injury must be adapted to fit the civil rights in question.","sumSrc":"Oyez","by":{"0":"35, 36, 38","1":"12, 17, 19","3":"3"}},{"t":"case","label":"Carpenter v. Nutter","cite":"59 P. 301","y":1899,"court":"Cal.","url":"https://www.courtlistener.com/c/P./59/301/","by":{"0":"passim"}},{"t":"case","label":"Castellano v. Fragozo","cite":"352 F.3d 939","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/352/939/","op":1,"by":{"0":"13"}},{"t":"case","label":"City of Newport v. Fact Concerts, Inc.","cite":"453 U.S. 247","y":1981,"id":"1980/80-396","sc":1,"sum":"Respondents (an organization licensed by petitioner city to present certain musical concerts, and a promoter of the concerts) brought suit in Federal District Court against the city and city officials. Alleging, inter alia, that the city's cancellation of the license amounted to a violation of their constitutional rights under color of.state law, repondents sought compensatory and punitive damages under 42 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"op":2,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"57"}},{"t":"case","label":"Cordova v. City of Albuquerque","cite":"816 F.3d 645","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/816/645/","ar":1,"by":{"0":"12","2":"1, 14, 40"}},{"t":"case","label":"Coxe v. Smithe (1662) 83 Eng. Rep. 327","cite":"1 Lev. 119","url":"https://www.courtlistener.com/c/Lev./1/119/","by":{"0":"28"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"0":"25","1":"30"}},{"t":"case","label":"DePaola v. Clarke","cite":"884 F.3d 481","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/884/481/","sum":"Observing with respect to an Eighth Amendment claim for refusal to provide medical treatment that “this principle does not apply to claims that fail to identify acts or omissions within the statutory limitation period that are a component of the deliberate indifference claim”.","sumSrc":"brief:2","by":{"0":"17, 46, 54","2":"35"}},{"t":"case","label":"Devereaux v. Abbey","cite":"263 F.3d 1070","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/263/1070/","by":{"0":"41"}},{"t":"case","label":"Drews v. Williams","cite":"23 So. 897","y":1898,"court":"La.","url":"https://www.courtlistener.com/c/So./23/897/","sum":"Observing, with respect to a one-year limitation, that “[i]njury runs from the day the damage was sustained (Rev. Civ. Code, § 3502), but the pleader must prove that the damages were incurred the year preceding the institution of the suit”.","sumSrc":"brief:2","by":{"0":"45","2":"35"}},{"t":"case","label":"Duncan v. Louisiana","cite":"391 U.S. 145","y":1968,"id":"1967/410","sc":1,"sum":"The Court ruled that the right to a jury trial in state prosecutions where sentences may be as long as two years were protected under the Sixth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Everett v. Henderson","cite":"14 N.E. 932","y":1888,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./14/932/","by":{"0":"28"}},{"t":"case","label":"Fields v. Wharrie","cite":"740 F.3d 1107","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/740/1107/","by":{"0":"25"}},{"t":"case","label":"Findley v. Bullock","cite":"1 Blackf. 467","y":1818,"court":"Ind.","url":"https://www.courtlistener.com/c/Blackf./1/467/","by":{"0":"15, 29"}},{"t":"case","label":"Floyd v. Attorney General","cite":"722 F. App’x 112","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/722/112/","op":1,"by":{"0":"13"}},{"t":"case","label":"Foss v. Whitehouse","cite":"48 A. 109","y":1901,"court":"Me.","url":"https://www.courtlistener.com/c/A./48/109/","sum":"Describing wrongful prosecution as a “continuous tort, though composed of numerous links”.","sumSrc":"brief:0","by":{"0":"47","2":"35"}},{"t":"case","label":"Gallo v. City of Philadelphia","cite":"161 F.3d 217","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/161/217/","by":{"0":"42"}},{"t":"case","label":"Garnett v. Undercover Officer C0039","cite":"838 F.3d 265","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/838/265/","op":1,"sum":"Explaining that “a further deprivation of liberty can result from the fabrication of evidence even if the initial arrest is lawful”.","sumSrc":"opinion","by":{"0":"12, 51","2":"17, 23","3":"3"}},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"sum":"The Court held that the Fourth Amendment entitles a person arrested without a warrant and charged by information to a timely preliminary hearing on probable cause.","sumSrc":"Oyez","by":{"0":"33, 40","2":"31"}},{"t":"case","label":"Green v. Bock Laundry Mach. Co.","cite":"490 U.S. 504","y":1989,"id":"1988/87-1816","sc":1,"sum":"Rule 609(a)(1) requires a judge to permit impeachment of a civil witness with evidence of prior felony convictions regardless of ensuant unfair prejudice to the witness or the party offering the testimony. Thus, the District Court did not err in allowing the jury to learn through impeaching cross-examination that Green was a convicted felon.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"57"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"op":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"0":"passim","1":"11"}},{"t":"case","label":"Grupo Dataflux v. Atlas Glob. Grp., L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Court ruled that allowing diversity jurisdiction to change after a case is filed would create uncertainty and expensive litigation that dealt with jurisdiction rather than the merits of the case. \"Uncertainty regarding the question of jurisdiction is particularly undesirable, and collateral litigation on the point particularly wasteful,\" wrote Justice Scalia. \"The stability provided by our time tested rule (of requiring diversity at the time of filing) weighs heavily against the approval of any new deviation.\".","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Hall v. Spencer Cty.","cite":"583 F.3d 930","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/583/930/","by":{"0":"54"}},{"t":"case","label":"Hamilton v. Manhattan Ry. Co.","cite":"9 N.Y.S. 313","y":1890,"court":"Super. Ct.","url":"https://www.courtlistener.com/c/N.Y.S./9/313/","op":7,"by":{"0":"45","2":"35"}},{"t":"case","label":"Hartman v. Moore","cite":"547 U.S. 250","y":2006,"id":"2005/04-1495","sc":1,"sum":"The Court ruled in favor of the postal inspectors, overruling the Court of Appeals. The opinion by Justice David Souter held that plaintiffs alleging retaliatory prosecution must prove that the law enforcement agents lacked probable cause. Probable cause, the Court ruled, is a crucial component of the \"chain of causation\" needed to evaluate retaliatory prosecution charges.","sumSrc":"Oyez","by":{"0":"25, 36","1":"17","3":"21"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 17, 45","2":"34"}},{"t":"case","label":"Heard v. Sheahan","cite":"253 F.3d 316","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/253/316/","by":{"0":"45","2":"35"}},{"t":"case","label":"Heath v. Bd. of Supervisors for S. Univ. & Agric. & Mech. Coll.","cite":"850 F.3d 731","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/731/","by":{"0":"54"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"op":34,"ar":10,"sum":"Noting possibility of abstention.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"8, 23, 27, 28, 41","3":"passim"}},{"t":"case","label":"Heimeshoff v. Hartford Life & Accident Ins. Co.","cite":"571 U.S. 99","y":2013,"id":"2013/12-729","sc":1,"sum":"The Court held that the Employment Retirement Income Security Act does not mandate a statute of limitations, allowing both parties in an insurance suit to mutually agree on a timeframe in which civil suits may be brought to court.","sumSrc":"Oyez","by":{"0":"16, 21, 32","3":"9"}},{"t":"case","label":"Hensley v. Mun. Court, San Jose Milpitas Judicial Dist.","cite":"411 U.S. 345","y":1973,"id":"1972/71-1428","sc":1,"op":2,"sum":"Restraints imposed on petitioner who was released on his own recognizance constitute \"custody\" within the meaning of the federal habeas corpus statute, 28 U. S. C. §§2241 (c) (3), 2254 (a). Pp. 348-353. 453 F. 2d 1252, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 33"}},{"t":"case","label":"Hernandez-Cuevas v. Taylor","cite":"723 F.3d 91","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/723/91/","by":{"0":"40, 41","3":"6"}},{"t":"case","label":"Jackson v. Barnes","cite":"749 F.3d 755","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/749/755/","by":{"0":"38"}},{"t":"case","label":"Justices of Bos. Mun. Court v. Lydon","cite":"466 U.S. 294","y":1984,"id":"1983/82-1479","sc":1,"op":2,"sum":"Under Massachusetts law, a defendant charged with certain minor crimes in Boston Municipal Court may elect to have a bench trial or a jury trial. If he chooses a jury trial and is convicted, he has the normal appellate process open to him, but if he chooses a bench trial and is dissatisfied with the results, he has an absolute right to a trial de novo before a jury and need not allege error at the bench trial to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 32, 33","3":"10"}},{"t":"case","label":"King v. Harwood","cite":"852 F.3d 568","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/568/","by":{"0":"13"}},{"t":"case","label":"Klehr v. A.O. Smith Corp.","cite":"521 U.S. 179","y":1997,"id":"1996/96-663","sc":1,"sum":"No and No. Justice Stephen Breyer wrote the opinion for a unanimous Court. The \"last predicate rule...lengthens the limitations period dramatically\" and thereby contradicts Congress's intention of ensuring a time limit for civil RICO claims.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Klein v. City of Beverly Hills","cite":"865 F.3d 1276","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/1276/","op":1,"sum":"Rejecting rule that forces litigants to file unripe Section 1983 suits.","sumSrc":"brief:0","by":{"0":"55"}},{"t":"case","label":"Lewis v. City of Chicago","cite":"914 F.3d 472","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/914/472/","op":1,"by":{"0":"34, 41"}},{"t":"case","label":"Loumiet v. United States","cite":"828 F.3d 935","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/828/935/","by":{"0":"47"}},{"t":"case","label":"Lowe v. Wartman","cite":"1 A. 489","y":1885,"court":"N.J.","url":"https://www.courtlistener.com/c/A./1/489/","by":{"0":"29"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Maldonado v. Harris","cite":"370 F.3d 945","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/370/945/","by":{"0":"54"}},{"t":"case","label":"Manuel v. City of Joliet","cite":"137 S. Ct. 911","y":2017,"id":"2016/14-9496","sc":1,"sum":"The Court held that an individual’s right to be free from unreasonable search and seizure continues throughout the legal process of a criminal case.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim, 22","3":"passim"}},{"t":"case","label":"Manuel v. City of Joliet","cite":"903 F.3d 667","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/903/667/","by":{"0":"passim","3":"16"}},{"t":"case","label":"Mayer v. Walter","cite":"64 Pa. 283","y":1870,"url":"https://www.courtlistener.com/c/Pa./64/283/","by":{"0":"26"}},{"t":"case","label":"Michaels v. McGrath","cite":"531 U.S. 1118","y":2001,"url":"https://supreme.justia.com/cases/federal/us/531/1118/","sc":1,"op":4,"ar":1,"by":{"0":"25","3":"21"}},{"t":"case","label":"Miller v. Pate","cite":"386 U.S. 1","y":1967,"id":"1966/250","sc":1,"sum":"The Fourteenth Amendment cannot tolerate a state criminal conviction secured by the knowing use of false evidence. Mooney v. Holohan, 294 U. S. 103, followed. Pp. 2-7. 342 F. 2d 646, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 39, 41, 51","1":"14"}},{"t":"case","label":"Mills v. Barnard","cite":"869 F.3d 473","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/473/","op":2,"by":{"0":"13, 54"}},{"t":"case","label":"Missouri v. McNeely","cite":"569 U.S. 141","y":2013,"id":"2012/11-1425","sc":1,"sum":"The Court held that the Fourth Amendment protects against the warrantless taking of a blood sample under exigent circumstances.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Mondragón v. Thompson","cite":"519 F.3d 1078","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/519/1078/","by":{"0":"13, 26"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Mooney v. Holohan","cite":"294 U.S. 103","y":1935,"id":"scdb/1934-145","sc":1,"ar":3,"sum":"1. The due process clause of the Fourteenth Amendment governs any action of a State through its legislature, its courts, or its executive officers, including action through its prosecuting officers.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 39, 41, 51","1":"14, 16","3":"19"}},{"t":"case","label":"Morse v. Fusto","cite":"804 F.3d 538","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/804/538/","sum":"Finding that a prosecutor may be liable for harm caused by fabricated evidence that was “material to the grand jury’s decision to indict”.","sumSrc":"brief:1","by":{"0":"42","1":"16, 25"}},{"t":"case","label":"Murphy v. Lynn","cite":"118 F.3d 938","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/118/938/","by":{"0":"42"}},{"t":"case","label":"Napue v. Illinois","cite":"360 U.S. 264","y":1959,"id":"1958/583","sc":1,"op":1,"sum":"The failure of the prosecutor-to correct the testimony of the witness which he knew to be false denied petitioner due process of law in violation of-the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 39","1":"14","2":"26"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Morgan","cite":"536 U.S. 101","y":2002,"id":"2001/00-1614","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964 precludes recovery for discrete acts of discrimination or retaliation that occur outside the statutory time period.","sumSrc":"Oyez","by":{"0":"45, 46, 49","2":"33, 34"}},{"t":"case","label":"Nebraska Press Ass’n v. Stuart","cite":"427 U.S. 539","y":1976,"id":"1975/75-817","sc":1,"op":1,"sum":"The Court agreed with the trial judge that the murder case would generate \"intense and pervasive pretrial publicity.\" However, the unanimous court held that the practical problems associated with implementing a prior restraint on the press in this case would not have served the accused's rights.","sumSrc":"Oyez","by":{"0":"42, 43","1":"17"}},{"t":"case","label":"Novella v. Westchester Cty.","cite":"661 F.3d 128","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/661/128/","by":{"0":"53"}},{"t":"case","label":"Owens v. Okure","cite":"488 U.S. 235","y":1989,"id":"1988/87-56","sc":1,"op":6,"sum":"The Court held that, when a state has multiple statutes of limitations for intentional torts, courts should use the general statute of limitations for claims of liability under 42 U.S.C. 1983.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Panetti v. Quarterman","cite":"551 U.S. 930","y":2007,"id":"2006/06-6407","sc":1,"op":1,"sum":"Noting that a scheme requiring “conscientious defense attorneys” to fle unripe suits “would add to the burden imposed on courts, applicants, and the States, with no clear advantage to any”.","sumSrc":"opinion","by":{"0":"19, 55"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"op":5,"ar":1,"sum":"Noting the “strong policy requiring exhaustion of state remedies” in order “to avoid the unnecessary friction between the federal and state court systems”.","sumSrc":"opinion","by":{"0":"passim","1":"27, 28","2":"27, 30","3":"passim"}},{"t":"case","label":"Prince v. Hicks","cite":"198 F.3d 607","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/607/","by":{"0":"25"}},{"t":"case","label":"Printup Bros. & Co. v. Smith","cite":"74 Ga. 157","y":1885,"court":"Ga.","url":"https://www.courtlistener.com/c/Ga./74/157/","by":{"0":"29"}},{"t":"case","label":"Pyle v. Kansas","cite":"317 U.S. 213","y":1942,"id":"scdb/1942-029","sc":1,"sum":"1. Habeas corpus is a remedy available in the state courts of Kansas to persons imprisoned in violation of rights guaranteed by the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"14"}},{"t":"case","label":"Quackenbush v. Allstate Ins. Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"op":1,"sum":"The Court held that an abstention-based remand order is appealable because the \"remand order here falls within that narrow class of collateral orders that are immediately appealable.\" Further, the Court held that the \"federal courts have the power to dismiss or remand cases based on abstention principles only where the relief sought is equitable or otherwise discretionary,\" and because \"this was a damages action, the District Court's remand order was an unwarranted application of the Burford doctrine.\" Justices Antonin Scalia and Anthony M. Kennedy wrote concurring opinions.","sumSrc":"Oyez","by":{"0":"58"}},{"t":"case","label":"Rawlings v. Ray","cite":"312 U.S. 96","y":1941,"id":"scdb/1940-056","sc":1,"sum":"1. The state statute of limitations applies in an action by the receiver of an insolvent national bank against a stockholder to collect a Comptroller's assessment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","2":"30"}},{"t":"case","label":"Reiter v. Cooper","cite":"507 U.S. 258","y":1993,"id":"1992/91-1496","sc":1,"op":1,"sum":"The Interstate Commerce Act (ICA) requires that motor common carriers charge the tariff rates they file with the Interstate Commerce Commission (ICC), 49 U. S. C. § 10762, and that such rates be \"reasonable,\" § 10701(a). Between 1984 and 1986, petitioner shippers tendered shipments to Carolina Motor Express, Inc., a motor carrier subject to ICC regulation, at negotiated rates that were lower than the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Riddle v. Riepe","cite":"866 F.3d 943","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/866/943/","by":{"0":"51"}},{"t":"case","label":"SEC v. Dresser Indus., Inc.","cite":"628 F.2d 1368","y":1980,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/628/1368/","op":1,"by":{"0":"44, 56"}},{"t":"case","label":"Schenck v. Butsch","cite":"32 Ind. 338","y":1869,"url":"https://www.courtlistener.com/c/Ind./32/338/","by":{"0":"28"}},{"t":"case","label":"Scheuerman v. City of Huntsville","cite":"373 F. Supp. 2d 1251","y":2005,"court":"N.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/373/1251/","by":{"0":"57"}},{"t":"case","label":"Shackelford v. Staton","cite":"23 S.E. 101","y":1895,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./23/101/","sum":"Rejecting plaintiff’s argument that the limitation period ran from the date on which she was damaged by clerk of the court’s failure to index a judgment, and holding that the period ran from the date of the clerk’s last omission, i.e., the day he ceased to be a clerk.","sumSrc":"brief:2","by":{"0":"17, 45","2":"35"}},{"t":"case","label":"Soldal v. Cook Cty.","cite":"506 U.S. 56","y":1992,"id":"1992/91-6516","sc":1,"op":1,"sum":"The seizure and removal of the trailer home implicated petitioners' Fourth Amendment rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","3":"18"}},{"t":"case","label":"Spencer v. Kemna","cite":"523 U.S. 1","y":1998,"id":"1997/96-7171","sc":1,"sum":"The Court held that the expiration of Spencer's sentence caused his petition to be moot because it no longer presented an Article III case or controversy. The Court concluded that once a petitioner's sentence has expired he must demonstrate a concrete and continuing injury to maintain suit.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Sprint Commc’ns, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"sum":"The Court held that a federal court does not need to abstain from deciding a case only because there is a case in state court that deals with the same subject matter.","sumSrc":"Oyez","by":{"0":"58"}},{"t":"case","label":"Tribble v. Tew","cite":"653 F. App’x 666","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/653/666/","by":{"0":"56"}},{"t":"case","label":"United States v. Agurs","cite":"427 U.S. 97","y":1976,"id":"1975/75-491","sc":1,"ar":3,"sum":"The prosecutor's failure to tender Sewell's criminal record to the defense did not deprive respondent of a fair trial as guaranteed by the Due Process Clause of the Fifth Amendment, where it appears that the record was not requested by defense counsel and gave rise to no inference -of perjury, that the trial judge remained convinced of respondent's guilt beyond a reasonable doubt after considering the criminal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"25, 26","2":"26"}},{"t":"case","label":"United States v. James Daniel Good Real Prop.","cite":"510 U.S. 43","y":1993,"id":"1993/92-1180","sc":1,"op":4,"sum":"Four and one-half years after police found drugs and drug paraphernalia in claimant Good's home and he pleaded guilty to promoting a harmful drug in violation of Hawaii law, the United States filed an in rem action in the Federal District Court, seeking forfeiture of his house and land, under 21 U. S. C. §881(a)(7), on the ground that the property had been used to commit or facilitate the commission of a federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"United States v. Kissel","cite":"218 U.S. 601","y":1910,"id":"scdb/1910-038","sc":1,"sum":"Under the Criminal Appeals Act of.March 2, 1907, c. 2564, 34 Stat. 1246, when the indictment is quashed this court is confined to a consideration of the grounds of decision mentioned in such statute, United States v. Keitel, 211 U. S. 370,.and there isá similar limit when the case comes up from a judgment sustaining a special plea in bar.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"United States v. Marion","cite":"404 U.S. 307","y":1971,"id":"1971/70-19","sc":1,"sum":"Appellees, claiming that the Government had known of the crimes with which they were charged, the circumstances of the crimes, and appellees' identities for over three years before they were indicted, moved to dismiss on the ground that the indictment was returned \"an unreasonably oppressive and unjustifiable time after the alleged offenses,\" and that the delay deprived them of rights to due process of law and a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Valencia v. Brown","cite":"2010 WL 8358087","y":2010,"court":"S.D.N.Y. Oct. 25","by":{"0":"50"}},{"t":"case","label":"Wallace v. Kato","cite":"549 U.S. 384","y":2007,"id":"2006/05-1240","sc":1,"op":13,"ar":5,"sum":"Noting the power of district courts to stay civil actions while criminal prosecutions proceed.","sumSrc":"opinion","by":{"0":"passim","1":"11, 12, 17, 21, 26, 29","2":"passim","3":"passim"}},{"t":"case","label":"Webb v. United States","cite":"789 F.3d 647","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/789/647/","by":{"0":"51"}},{"t":"case","label":"Whelan v. Abell","cite":"953 F.2d 663","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/953/663/","sum":"Describing wrongful prosecution as a “continuous tort, though composed of numerous links”.","sumSrc":"brief:0","by":{"0":"4, 17, 46, 47","2":"35","3":"15, 16"}},{"t":"case","label":"Wilkinson v. Goodfellow-Brooks Shoe Co.","cite":"141 F. 218","y":1905,"court":"C.C.E.D. Mo.","url":"https://www.courtlistener.com/c/F./141/218/","sum":"Holding, in “an action for malicious prosecution,” that “the institution of the proceedings and the subsequent appeal, if wrongfully done, constitute but one continuous tort for the purpose of this case”.","sumSrc":"brief:2","by":{"0":"46, 47","2":"36"}},{"t":"case","label":"Wilson v. Garcia","cite":"471 U.S. 261","y":1985,"id":"1984/83-2146","sc":1,"sum":"The Court held that, in situations where a federal action does not have a statute of limitations, the practice has been to adopt a local limitation as long as that limitation is not inconsistent with a federal law or policy.","sumSrc":"Oyez","by":{"0":"16","1":"12, 27"}},{"t":"case","label":"Winfrey v. Rogers","cite":"901 F.3d 483","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/901/483/","by":{"0":"54"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"op":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"58"}},{"t":"case","label":"Zahrey v. Coffey","cite":"221 F.3d 342","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/221/342/","op":1,"ar":1,"sum":"Holding that depriving someone of their liberty on the basis of fabricated evidence is a “classic constitutional violation: the deprivation of his liberty without due process of law”.","sumSrc":"brief:1","by":{"0":"25, 40","1":"14, 15, 16, 31","2":"19","3":"3, 5, 13, 21"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"passim","3":"passim"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"12, 43, 44, 56","1":"3, 13, 23","3":"22"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"passim","1":"3, 13, 15, 16"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"6, 12, 39","1":"3, 13","3":"passim"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":34,"ar":3,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"passim","1":"passim","3":"passim"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","subs":["(a)"],"stext":{"head":"§1988. Proceedings in vindication of civil rights","paras":[[0,"(a) Applicability of statutory and common law"],[0,"The jurisdiction in civil and criminal matters conferred on the district courts by the provisions of titles 13, 24, and 70 of the Revised Statutes for the protection of all persons in the United States in their civil rights, and for their vindication, shall be exercised and enforced in conformity with the laws of the United States, so far as such laws are suitable to carry the same into effect; but in all cases where they are not adapted to the object, or are deficient in the provisions necessary to furnish suitable remedies and punish offenses against law, the common law, as modified and changed by the constitution and statutes of the State wherein the court having jurisdiction of such civil or criminal cause is held, so far as the same is not inconsistent with the Constitution and laws of the United States, shall be extended to and govern the said courts in the trial and disposition of the cause, and, if it is of a criminal nature, in the infliction of punishment on the party found guilty."],[0,"(b) Attorney's fees"],[0,"In any action or proceeding to enforce a provision of sections 1981, 1981a, 1982, 1983, 1985, and 1986 of this title, title IX of Public Law 92–318 [20 U.S.C. 1681 et seq.], the Religious Freedom Restoration Act of 1993 [42 U.S.C. 2000bb et seq.], the Religious Land Use and Institutionalized Persons Act of 2000 [42 U.S.C. 2000cc et seq.], title VI of the Civil Rights Act of 1964 [42 U.S.C. 2000d et seq.], or section 12361 of title 34, the court, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee as part of the costs, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity such officer shall not be held liable for any costs, including attorney's fees, unless such action was clearly in excess of such officer's jurisdiction."],[0,"(c) Expert fees"],[0,"In awarding an attorney's fee under subsection (b) in any action or proceeding to enforce a provision of section 1981 or 1981a of this title, the court, in its discretion, may include expert fees as part of the attorney's fee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1988?type=usc&year=mostrecent&link-type=html"},"head":"§1988. Proceedings in vindication of civil rights","tname":"The Public Health and Welfare","by":{"0":"20","1":"11"}},{"t":"rule","label":"Fed. R. Civ. P. 8","url":"https://www.law.cornell.edu/rules/frcp/rule_8","subs":["(d)(2)"],"by":{"0":"56","3":"21"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(b)"],"by":{"0":"13","1":"5"}},{"t":"case","label":"Baker v. McCollan","cite":"443 U.S. 137","y":1979,"id":"1978/78-752","sc":1,"sum":"Respondent failed to satisfy § 1983's threshold requirement that the plaintiff be deprived of a right \"secured by the Constitution and laws,\" and hence had no claim cognizable under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 13"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":"1"}},{"t":"case","label":"Britton v. Maloney","cite":"196 F.3d 24","y":1999,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/196/24/","by":{"1":"15"}},{"t":"case","label":"Brower v. County of Inyo","cite":"489 U.S. 593","y":1989,"id":"1988/87-248","sc":1,"sum":"The Court held that a police roadblock could constitute an illegal seizure under the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Buckley v. Fitzsimmons","cite":"509 U.S. 259","y":1993,"id":"1992/91-7849","sc":1,"sum":"Petitioner Buckley sought damages, under 42 U. S. C. § 1983, from respondent prosecutors for fabricating evidence during the preliminary investigation of a highly publicized rape and murder in Illinois and making false statements at a press conference announcing the return of an indictment against him. He claimed that when three separate lab studies failed to make a reliable connection between a bootprint at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 31, 32","3":"21"}},{"t":"case","label":"Burns v. Reed","cite":"500 U.S. 478","y":1991,"id":"1990/89-1715","sc":1,"op":1,"sum":"A state prosecuting attorney is absolutely immune from liability for damages under § 1983 for participating in a probable-cause hearing, but not for giving legal advice to the police.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8, 30"}},{"t":"case","label":"Degen v. United States","cite":"517 U.S. 820","y":1996,"id":"1995/95-173","sc":1,"op":1,"sum":"Principles of deference to the other branches of government require a court to invoke its inherent power only as a reasonable response to the problems and needs that provoke it. No sufficient reason justifies disentitlement here.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"1":"11","2":"14"}},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"sum":"The Court held that prosecutors have the same absolute immunity under Section 1983 that they had under common law in malicious prosecution suits.","sumSrc":"Oyez","by":{"1":"4, 30"}},{"t":"case","label":"Kaley v. United States","cite":"571 U.S. 320","y":2014,"id":"2013/12-464","sc":1,"sum":"The Court held that the Fifth and Sixth Amendments do not allow an individual to use funds obtained illegally to pay for an attorney.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Lunsford v. Dietrich","cite":"9 So. 308","y":1891,"court":"Ala.","url":"https://www.courtlistener.com/c/So./9/308/","by":{"1":"25"}},{"t":"case","label":"Rehberg v. Paulk","cite":"566 U.S. 356","y":2012,"id":"2011/10-788","sc":1,"sum":"The Court held that a witness in a grand jury proceeding is entitled to the same absolute immunity from a §1983 action as a witness who testifies at trial.","sumSrc":"Oyez","by":{"1":"20","2":"14"}},{"t":"case","label":"Ricciuti v. N.Y.C. Transit Auth.","cite":"124 F.3d 123","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/123/","by":{"1":"16","2":"4, 16, 17, 19, 23, 24"}},{"t":"case","label":"Ruff v. Runyon","cite":"258 F.3d 498","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/258/498/","by":{"1":"1"}},{"t":"case","label":"Siegert v. Gilley","cite":"500 U.S. 226","y":1991,"id":"1990/90-96","sc":1,"op":1,"sum":"The Court of Appeals properly concluded that the District Court should have dismissed Siegert's suit because he had not overcome Gilley's qualified immunity defense. Siegert failed to allege the violation of a clearly established constitutional right -indeed, of any constitutional right at all-since, under Paul v. Davis, 424 U. S. 693, 708-709, injury to reputation by itself is not a protected \"liberty\" interest. He …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Strickler v. Greene","cite":"527 U.S. 263","y":1999,"id":"1998/98-5864","sc":1,"sum":"The Court held that although Strickler demonstrated cause for his failure to raise a Brady claim, Virginia did not violate Brady by failing to disclose exculpatory evidence to him.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Whitfield v. Westbrook","cite":"40 Miss. 311","y":1866,"url":"https://www.courtlistener.com/c/Miss./40/311/","by":{"1":"25"}},{"t":"case","label":"Whitlock v. Brueggemann","cite":"682 F.3d 567","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/682/567/","by":{"1":"14"}},{"t":"usc","label":"18 U.S.C. § 241","url":"https://www.law.cornell.edu/uscode/text/18/241","by":{"1":"9, 22, 30"}},{"t":"usc","label":"18 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/18/242","by":{"1":"9, 22, 30"}},{"t":"case","label":"Brady v. Maryland","cite":"373 U.S. 83","y":1963,"id":"1962/490","sc":1,"ar":4,"sum":"The Supreme Court held that the prosecution's suppression of evidence violated the Due Process Clause of the Fourteenth Amendment. The Court also held that according the Maryland state law, the confession would not exonerate Brady, so a remand only for reconsidering his punishment was proper.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Cameron v. City of New York","cite":"598 F.3d 50","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/598/50/","by":{"2":"16"}},{"t":"case","label":"Donahue v. Gavin","cite":"280 F.3d 371","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/280/371/","sum":"Holding that a nolle prosequi does not indicate innocence where “[t]he prosecutor simply reasoned that [the plaintiff] was not likely to receive any additional jail time if convicted in a retrial”.","sumSrc":"brief:2","by":{"2":"42"}},{"t":"case","label":"Glover v. City of Wilmington","cite":"966 F. Supp. 2d 417","y":2013,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/966/417/","by":{"2":"40"}},{"t":"case","label":"Halsey v. Pfeiffer","cite":"750 F.3d 273","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/750/273/","sum":"Describing prosecutor’s acknowledgment that “he would not have charged” the defendant in the absence of the fabricated evidence.","sumSrc":"brief:3","by":{"2":"24, 42","3":"3"}},{"t":"case","label":"Jovanovic v. City of New York","cite":"486 F. App’x 149","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/486/149/","by":{"2":"4, 17"}},{"t":"case","label":"Margheim v. Buljko","cite":"855 F.3d 1077","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/1077/","by":{"2":"42"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Miles v. Paul Mook of Ridgeland, Inc.","cite":"113 So. 3d 580","y":2012,"court":"Miss. Ct. App.","url":"https://www.courtlistener.com/c/So.%203d/113/580/","by":{"2":"40"}},{"t":"case","label":"Mitchell v. City of New York","cite":"841 F.3d 72","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/841/72/","by":{"2":"16"}},{"t":"case","label":"Monell v. Department of Social Services of City of New York","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Rentas v. Ruffin","cite":"816 F.3d 214","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/816/214/","by":{"2":"18, 19"}},{"t":"case","label":"Spencer v. Peters","cite":"857 F.3d 789","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/857/789/","by":{"2":"24","3":"14"}},{"t":"case","label":"vii United States v. Bagley","cite":"473 U.S. 667","y":1985,"id":"1984/84-48","sc":1,"op":2,"sum":"The Court held that the government’s failure to disclose the contacts in discovery did not violate the Due Process Clause. Justice Blackmun wrote that the state was required by due process to disclose evidence that was both favorable to the accused and material to either guilt or punishment, and that impeachment evidence fell within this requirement.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Wyatt v. Cole","cite":"504 U.S. 158","y":1992,"id":"1991/91-126","sc":1,"sum":"With the assistance of respondent Robbins, an attorney, respondent Cole filed a complaint under the Mississippi replevin statute against his partner, petitioner Wyatt. After Cole refused to comply with a state court order to return to Wyatt property seized under the statute, Wyatt brought suit in the Federal District Court under 42 U. S. C. § 1983, challenging the state statute's constitutionality and seeking …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"sum":"The Court found that that the conditions of confinement did not infringe upon a pretrial detainee's rights. Justice Rehnquist's opinion argued that the issue of prison management is ripe with \"judgment calls\" which rest outside the jurisdiction of the judiciary.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Erlin v. United States","cite":"364 F.3d 1127","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/1127/","by":{"3":"8"}},{"t":"case","label":"Kingsley v. Hendrickson","cite":"135 S. Ct. 2466","y":2015,"id":"2014/14-6368","sc":1,"sum":"The Court held that a pretrial detainee who brings an excessive force claim need only prove that the use of force in question was objectively unreasonable.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"Klen v. City of Loveland","cite":"661 F.3d 498","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/661/498/","by":{"3":"19"}},{"t":"case","label":"Kyles v. Whitley","cite":"514 U.S. 419","y":1995,"id":"1994/93-7927","sc":1,"ar":3,"sum":"The Supreme Court held that Kyles was entitled to a new trial because the net effect of the suppressed evidence raised a reasonable probability that the jury would have reached a different result. The Fifth Circuit used the wrong standard and failed to consider the cumulative effect of all the evidence that the prosecution failed to disclose.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Limone v. Condon","cite":"372 F.3d 39","y":2004,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/372/39/","by":{"3":"19"}},{"t":"case","label":"Mapp v. Ohio","cite":"367 U.S. 643","y":1961,"id":"1960/236","sc":1,"sum":"The Court decided that evidence obtained illegally may not be used against someone in a court of law by the Fourth Amendment.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Medtronic, Inc. v. Mirowski Family Ventures, LLC","cite":"571 U.S. 191","y":2014,"id":"2013/12-1128","sc":1,"sum":"The Court held that, in a patent infringement case, the burden of proof of infringement is on the patent holder.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Page(s) United States v. Galletti","cite":"541 U.S. 114","y":2004,"id":"2003/02-1389","sc":1,"op":58,"sum":"The Court held that the IRS' assessment against the partnership was sufficient to extend the statute of limitations by 10 years to collect the money from the partners themselves.","sumSrc":"Oyez","by":{"3":"20"}}]};